import React, { useState } from 'react';
import { 
  Star, MoreVertical, Edit2, Trash2, Pause, Play, 
  Copy, Archive, CheckCircle, AlertCircle, Clock, TrendingUp
} from 'lucide-react';

export const ImprovedProjectCard = ({ 
  project, 
  onToggleFavorite, 
  onEdit, 
  onDelete,
  onDuplicate,
  onArchive,
  onPause,
  onClick 
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const isFavorite = project.is_favorite || false;

  const completedTasks = project.tasks?.filter(t => t.status === 'completed').length || 0;
  const totalTasks = project.tasks?.length || 0;
  const progress = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

  const statusConfig = {
    planning: { 
      label: 'Planificación', 
      color: 'bg-yellow-100 text-yellow-700 border-yellow-300',
      icon: Clock
    },
    in_progress: { 
      label: 'En Progreso', 
      color: 'bg-blue-100 text-blue-700 border-blue-300',
      icon: TrendingUp
    },
    completed: { 
      label: 'Completado', 
      color: 'bg-green-100 text-green-700 border-green-300',
      icon: CheckCircle
    },
    on_hold: { 
      label: 'Pausado', 
      color: 'bg-gray-100 text-gray-700 border-gray-300',
      icon: Pause
    },
    cancelled: { 
      label: 'Cancelado', 
      color: 'bg-red-100 text-red-700 border-red-300',
      icon: AlertCircle
    }
  };

  const currentStatus = statusConfig[project.status] || statusConfig.planning;
  const StatusIcon = currentStatus.icon;

  const handleToggleFavorite = (e) => {
    e.stopPropagation();
    onToggleFavorite?.(project._id, !isFavorite);
  };

  return (
    <div 
      onClick={() => onClick?.(project)}
      className="bg-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 cursor-pointer transform hover:scale-105 border border-gray-200"
    >
      <div className={`h-2 rounded-t-xl ${
        project.priority === 'urgent' ? 'bg-red-500' :
        project.priority === 'high' ? 'bg-orange-500' :
        project.priority === 'medium' ? 'bg-blue-500' : 'bg-gray-400'
      }`} />

      <div className="p-6">
        <div className="flex items-start justify-between mb-4">
          <div className="flex-1 min-w-0 mr-3">
            <h3 className="text-lg font-bold text-gray-900 truncate mb-1">
              {project.project_name}
            </h3>
            <p className="text-sm text-gray-500 truncate">
              {project.client_id?.company_name}
            </p>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={handleToggleFavorite}
              className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
              title={isFavorite ? 'Quitar de favoritos' : 'Agregar a favoritos'}
            >
              <Star 
                className={`w-5 h-5 ${
                  isFavorite 
                    ? 'fill-yellow-400 text-yellow-400' 
                    : 'text-gray-400'
                }`} 
              />
            </button>

            <div className="relative">
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  setIsMenuOpen(!isMenuOpen);
                }}
                className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
              >
                <MoreVertical className="w-5 h-5 text-gray-600" />
              </button>

              {isMenuOpen && (
                <>
                  <div 
                    className="fixed inset-0 z-10" 
                    onClick={(e) => {
                      e.stopPropagation();
                      setIsMenuOpen(false);
                    }}
                  />
                  <div className="absolute right-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-gray-200 py-2 z-20">
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onEdit?.(project);
                        setIsMenuOpen(false);
                      }}
                      className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-gray-50 text-gray-700"
                    >
                      <Edit2 className="w-4 h-4" />
                      <span>Editar proyecto</span>
                    </button>

                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onDuplicate?.(project);
                        setIsMenuOpen(false);
                      }}
                      className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-gray-50 text-gray-700"
                    >
                      <Copy className="w-4 h-4" />
                      <span>Duplicar proyecto</span>
                    </button>

                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onPause?.(project);
                        setIsMenuOpen(false);
                      }}
                      className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-gray-50 text-gray-700"
                    >
                      {project.status === 'on_hold' ? (
                        <>
                          <Play className="w-4 h-4" />
                          <span>Reanudar proyecto</span>
                        </>
                      ) : (
                        <>
                          <Pause className="w-4 h-4" />
                          <span>Pausar proyecto</span>
                        </>
                      )}
                    </button>

                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onArchive?.(project);
                        setIsMenuOpen(false);
                      }}
                      className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-gray-50 text-gray-700"
                    >
                      <Archive className="w-4 h-4" />
                      <span>Archivar proyecto</span>
                    </button>

                    <div className="border-t my-2" />

                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onDelete?.(project);
                        setIsMenuOpen(false);
                      }}
                      className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-red-50 text-red-600"
                    >
                      <Trash2 className="w-4 h-4" />
                      <span>Eliminar proyecto</span>
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2 mb-4">
          <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold border ${currentStatus.color}`}>
            <StatusIcon className="w-3.5 h-3.5" />
            {currentStatus.label}
          </span>
        </div>

        <div className="mb-4">
          <div className="flex justify-between text-sm mb-2">
            <span className="text-gray-600 font-medium">Progreso</span>
            <span className="text-gray-900 font-bold">{Math.round(progress)}%</span>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
            <div
              className="bg-gradient-to-r from-green-500 to-emerald-600 h-3 rounded-full transition-all duration-500 ease-out"
              style={{ width: `${progress}%` }}
            />
          </div>
          <p className="text-xs text-gray-500 mt-1">
            {completedTasks} de {totalTasks} tareas completadas
          </p>
        </div>

        <div className="flex items-center justify-between text-sm border-t pt-4">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1.5 text-gray-600">
              <CheckCircle className="w-4 h-4" />
              <span>{completedTasks}/{totalTasks}</span>
            </div>
            <div className="flex items-center gap-1.5 text-gray-600">
              <Clock className="w-4 h-4" />
              <span className="text-xs">
                {new Date(project.estimated_end_date).toLocaleDateString('es-ES', {
                  day: 'numeric',
                  month: 'short'
                })}
              </span>
            </div>
          </div>

          {isFavorite && (
            <div className="flex items-center gap-1 text-yellow-600 text-xs font-semibold">
              <Star className="w-3 h-3 fill-current" />
              Favorito
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
